struct Gaussian {double value=NAN,error=NAN;int status=-999;};
Gaussian gaussian(const Values&v){Gaussian out;if(v.size()<30)return out;double m=mean(v),sd=m*rms(v);if(!(m>0&&sd>0))return out;TH1D h("pilot_fit_hist","",240,.3*m,1.7*m);for(double x:v)h.Fill(x);TF1 f("pilot_gaussian","gaus",.015,10);f.SetParameters(h.GetMaximum(),m,sd);auto result=h.Fit(&f,"QSN","",std::max(.015,m-3*sd),m+3*sd);out.status=int(result);if(out.status)return out;m=f.GetParameter(1);sd=std::abs(f.GetParameter(2));if(!(m>0&&sd>0))return out;result=h.Fit(&f,"QSN","",std::max(.015,m-1.5*sd),m+1.5*sd);out.status=int(result);m=f.GetParameter(1);sd=std::abs(f.GetParameter(2));if(out.status||!(m>0&&sd>0))return out;out.value=sd/m;if(result.Get()){double sign=f.GetParameter(2)>0?1:-1;double var=result->CovMatrix(2,2)/(m*m)+sd*sd*result->CovMatrix(1,1)/std::pow(m,4)-2*sign*sd*result->CovMatrix(1,2)/std::pow(m,3);out.error=std::sqrt(std::max(0.,var));}return out;}
struct Metric {size_t n=0;double mean=NAN,rms=NAN,core=NAN,hits=NAN,hitsSE=NAN;Gaussian gaus;};
Metric metric(const Values&e,const Values&n,bool fits=true){Metric m;m.n=e.size();if(e.size()<21)return m;auto w=width(e);m.mean=w.mean;m.rms=w.rms;m.core=w.core;Stats s;for(double x:n)s.add(x);m.hits=s.mean;m.hitsSE=s.sem();if(fits)m.gaus=gaussian(e);return m;}
using Blocks=std::map<int,std::vector<std::vector<size_t>>>;
Blocks recordBlocks(const std::vector<Record>&v){std::map<int,std::map<long long,std::vector<size_t>>>map;for(size_t i=0;i<v.size();++i)map[v[i].file][v[i].entry/100].push_back(i);Blocks out;for(auto&f:map)for(auto&b:f.second)out[f.first].push_back(std::move(b.second));return out;}
std::vector<size_t>resample(const Blocks&b,std::mt19937_64&rng){std::vector<size_t>v;for(auto&f:b){auto&blocks=f.second;for(size_t i=0;i<blocks.size();++i){auto&chosen=blocks[std::uniform_int_distribution<size_t>(0,blocks.size()-1)(rng)];v.insert(v.end(),chosen.begin(),chosen.end());}}return v;}
void writeMetric(std::ostream&o,int beam,const std::string&selection,const std::string&sample,const Metric&m){o<<beam<<'\t'<<selection<<'\t'<<sample<<'\t'<<m.n<<'\t'<<m.mean<<'\t'<<m.rms<<'\t'<<m.core<<'\t'<<m.gaus.value<<'\t'<<m.gaus.error<<'\t'<<m.gaus.status<<'\t'<<m.hits<<'\t'<<m.hitsSE<<'\n';}
